# Data
diagonal_num_14 = [5, 9, 15, 25, 41, 67, 109, 177, 287, 465, 753, 1219, 1973]
steps_14 = list(range(1, len(diagonal_num_14) + 1))

plt.figure(figsize=(3.4, 2.2))  # One-column figure size

# Plot
plt.plot(steps_14, diagonal_num_14, marker='o', markersize=3, linewidth=1, color = '#008dff')

# Log scale for exponential growth
plt.yscale('log')

# Axis labels and ticks
plt.xlabel('Step', fontsize=9)
plt.ylabel('Number of Diagonals', fontsize=9)
plt.xticks(steps_14, fontsize=8)
plt.yticks(fontsize=8)



# Final layout and save
plt.tight_layout(pad=0.3)
plt.savefig(graph_folder + 'diagonalNum.pdf', format='pdf', bbox_inches='tight')
plt.close()

